import { OneClaw, AuditSink } from "@1claw/sdk";

const sink: AuditSink = {
  send(event) {
    fetch("https://your-siem.example.com/ingest", {
      method: "POST",
      body: JSON.stringify(event),
    });
  },
};

const client = new OneClaw({
  token: process.env.ONECLAW_TOKEN,
  auditSink: sink,
});
